import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`google-maps-ranking`,heroTitle:`Dominate the local map pack in minutes`,heroSubtitle:`Perplexity Computer checks where you rank in Google Maps, audits your business profile, and delivers a local fix list automatically.`,inputUrlCta:`Check my rankings`,inputUrlPlaceholder:`Business name, city`,inputUrlPrefill:`Use {url} as the business name and location for a Google Maps ranking audit. Search Google Maps for the highest-value services this business should rank for, record the current position for each query, identify the top 3 competitors in the map pack, and audit the Google Business Profile for missing categories, weak photos, review gaps, service area issues, and incomplete fields. Deliver a prioritized improvement plan that explains how to improve map visibility, review coverage, local landing pages, and profile completeness.`,heroOverlaySteps:[`Searching Google Maps for your priority services and location terms`,`Comparing your listing against the top map pack competitors`,`Auditing categories, photos, reviews, and business profile completeness`,`Ranking gaps and local optimization fixes prioritized by impact`],generatingSteps:[`Searching Google Maps and local search results for the business details in {url}`,`Designing an agent to capture ranking position, competitor signals, and profile gaps`,`Configuring local SEO checks for categories, reviews, photos, and citations`,`Preparing a map pack improvement plan with clear next actions`],featureSectionTitle:`From business listing to local growth plan`,featureCardTitles:[`Connects to your local marketing stack`,`A fix list you can execute`],featureCardDescriptions:[`Computer combines local search research, profile auditing, competitor benchmarking, and prioritization using the right model for each job.`,`Google Business Profile, Sheets, Notion, and Drive fit into one workflow so audits and fix lists are easy to hand off.`,`Map pack rankings, competitor comparisons, profile issues, and local SEO recommendations come back structured for immediate action.`],capabilitySectionTitle:`Your local ranking analyst, on demand`,capabilitySectionSubtitle:`Enter your business and city, then come back to a concrete plan for climbing Google Maps.`,capabilityCards:[{title:`Maps Ranking Checks`,description:`Computer can test the service queries that matter most and record exactly where you appear in the local pack today.`},{title:`Competitor Gap Analysis`,description:`Computer can compare your profile against the businesses already ranking above you to surface the signals they have and you do not.`},{title:`Profile Optimization Plan`,description:`Computer can identify missing categories, weak photos, sparse review coverage, and incomplete business details, then turn them into a prioritized fix list.`},{title:`Connect Your Tools`,description:`Computer can push findings into Sheets, Docs, and planning systems so owners and operators can work from one source of truth.`},{title:`Remember Your Locations`,description:`Computer can remember locations, services, and prior audits so recurring local SEO work builds over time.`},{title:`Track Rank Movement`,description:`Computer can re-run your ranking checks on a cadence and flag when you move up, slip, or lose coverage to a competitor.`}]});export{t as default};
